const input = $input.first().json;
const acao = input.acao || '';
const CAL_TOKEN = $env.CAL_API_KEY;
const EVENT_TYPE_ID = 5649539;
const BASE = 'https://api.cal.com/v2';
const SUPA_KEY = $env.SUPABASE_SERVICE_ROLE_KEY;
const calAuth = { 'Authorization': 'Bearer ' + CAL_TOKEN, 'cal-api-version': '2024-09-04' };

if (acao === 'verificarAgenda') {
  const start = input.start || input.startTime || '';
  const end = input.end || input.endTime || '';

  async function fetchSlots(rangeStart, rangeEnd) {
    return await this.helpers.httpRequest({
      method: 'GET',
      url: BASE + '/slots',
      headers: calAuth,
      qs: {
        start: rangeStart,
        end: rangeEnd,
        eventTypeId: EVENT_TYPE_ID,
        timeZone: 'America/Sao_Paulo',
        duration: 30,
        format: 'time'
      },
      ignoreHttpStatusErrors: true
    });
  }

  function extractSlots(data) {
    if (!data || data.status === 'error' || data.error || data.message) {
      return { error: 'Erro ao verificar agenda Cal.com: ' + JSON.stringify(data).slice(0, 500), slots: [], lines: [] };
    }

    const rawSlots = (data.data && data.data.slots) ? data.data.slots : (data.data || {});
    const slotList = [];

    for (const date of Object.keys(rawSlots)) {
      const times = Array.isArray(rawSlots[date]) ? rawSlots[date] : [];
      for (const t of times) {
        const slotStart = typeof t === 'string' ? t : (t.start || t.time || t.startTime || '');
        if (!slotStart) continue;
        const dt = new Date(slotStart);
        if (Number.isNaN(dt.getTime())) continue;
        slotList.push({ date, slotStart, dt });
      }
    }

    slotList.sort(function(a, b) { return a.dt - b.dt; });

    const grouped = {};
    for (const slot of slotList) {
      const dateLabel = new Date(slot.date + 'T12:00:00Z').toLocaleDateString('pt-BR', {
        timeZone: 'America/Sao_Paulo',
        weekday: 'long',
        day: '2-digit',
        month: '2-digit'
      });
      const timeLabel = slot.dt.toLocaleTimeString('pt-BR', {
        timeZone: 'America/Sao_Paulo',
        hour: '2-digit',
        minute: '2-digit'
      });
      if (!grouped[dateLabel]) grouped[dateLabel] = [];
      grouped[dateLabel].push(timeLabel);
    }

    const lines = Object.keys(grouped).map(function(dateLabel) {
      return dateLabel + ': ' + grouped[dateLabel].slice(0, 12).join(', ');
    });

    return { error: null, slots: slotList, lines };
  }

  const data = await fetchSlots.call(this, start, end);
  const primary = extractSlots(data);
  if (primary.error) return [{ json: { _route: 'done', output: primary.error } }];

  if (primary.lines.length > 0) {
    return [{
      json: {
        _route: 'done',
        output: ['Horarios disponiveis:'].concat(primary.lines).join(String.fromCharCode(10))
      }
    }];
  }

  // Se o periodo solicitado nao tem horario, busca automaticamente alternativas nos proximos 7 dias.
  const baseDate = start ? new Date(start) : new Date();
  const altStartDate = Number.isNaN(baseDate.getTime()) ? new Date() : baseDate;
  const altEndDate = new Date(altStartDate.getTime() + 7 * 24 * 60 * 60 * 1000);
  const altStart = altStartDate.toISOString();
  const altEnd = altEndDate.toISOString();
  const altData = await fetchSlots.call(this, altStart, altEnd);
  const alternatives = extractSlots(altData);
  if (alternatives.error) return [{ json: { _route: 'done', output: alternatives.error } }];

  const firstTwo = alternatives.slots.slice(0, 2).map(function(slot) {
    const dateLabel = slot.dt.toLocaleDateString('pt-BR', {
      timeZone: 'America/Sao_Paulo',
      weekday: 'long',
      day: '2-digit',
      month: '2-digit'
    });
    const timeLabel = slot.dt.toLocaleTimeString('pt-BR', {
      timeZone: 'America/Sao_Paulo',
      hour: '2-digit',
      minute: '2-digit'
    });
    return dateLabel + ' as ' + timeLabel;
  });

  const output = firstTwo.length > 0
    ? ['Encontrei estas 2 opcoes disponiveis. Ofereca ao lead sem dizer que nao ha horario:'].concat(firstTwo).join(String.fromCharCode(10))
    : 'Sem horarios disponiveis no periodo solicitado e tambem nao encontrei alternativas nos proximos 7 dias. Janela consultada: ' + start + ' ate ' + end;

  return [{
    json: {
      _route: 'done',
      output
    }
  }];
}

if (acao === 'criar_agendamento') {
  const emailRaw = (input.email || '').trim();
  const finalEmail = (emailRaw.includes('@') && !emailRaw.endsWith('@nexosleads.com'))
    ? emailRaw
    : emailRaw.replace('@nexosleads.com', '') + '@nexosleads.com';
  const rawPhone = finalEmail.replace('@nexosleads.com', '').replace(/[^0-9]/g, '');
  const phone = rawPhone.startsWith('55') ? rawPhone : '55' + rawPhone;
  return [{ json: {
    _route: 'booking',
    _start: input.start,
    _eventTypeId: EVENT_TYPE_ID,
    _name: input.name || 'Lead',
    _email: finalEmail,
    _phone: phone,
    _notes: input.notes || input.description || ''
  } }];
}

if (acao === 'busca_evento_agenda') {
  const data = await this.helpers.httpRequest({
    method: 'GET',
    url: BASE + '/bookings',
    headers: calAuth,
    qs: { attendeeEmail: (input.email || '').trim(), status: 'upcoming', limit: 3 },
    ignoreHttpStatusErrors: true
  });
  const rawData = data && data.data ? data.data : null;
  const bookings = Array.isArray(rawData) ? rawData : (rawData && Array.isArray(rawData.bookings) ? rawData.bookings : []);
  if (!bookings.length) return [{ json: { _route: 'done', output: 'Nenhum agendamento futuro encontrado.' } }];
  const list = bookings.map(function(b) {
    const startTime = b.start || b.startTime || '';
    const dt = new Date(startTime);
    const dateStr = dt.toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', year: 'numeric' });
    const timeStr = dt.toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' });
    const uid = b.uid || b.bookingUid || b.id || '';
    return dateStr + ' as ' + timeStr + ' - UID: ' + uid;
  });
  return [{ json: { _route: 'done', output: ['Agendamentos:'].concat(list).join(String.fromCharCode(10)) } }];
}

if (acao === 'cancela_evento_agenda') {
  const data = await this.helpers.httpRequest({
    method: 'POST',
    url: BASE + '/bookings/' + input.bookingUid + '/cancel',
    headers: calAuth,
    body: { cancellationReason: 'Cancelado pelo lead via WhatsApp' },
    ignoreHttpStatusErrors: true
  });
  return [{ json: { _route: 'done', output: (data && data.status === 'success') ? 'Agendamento cancelado com sucesso.' : 'Erro ao cancelar: ' + JSON.stringify(data).slice(0, 150) } }];
}

return [{ json: { _route: 'done', output: 'Acao nao reconhecida: ' + acao } }];

const d = $input.first().json;
return [{ json: {
  start: d._start,
  eventTypeId: d._eventTypeId,
  name: d._name,
  email: d._email,
  notes: d._notes || ''
} }];

