const calResp = $input.first().json;
const orig = $('Processa Acoes').first().json;
const phone = orig._phone || '';
const finalEmail = orig._email || '';
const leadSummary = String(orig._notes || '').trim();
const BASE = 'https://api.cal.com/v2';
const CAL_TOKEN = $env.CAL_API_KEY;
const SUPA_URL = 'https://fidyajgmzyfmthygseuy.supabase.co/rest/v1';
const SUPA_KEY = $env.SUPABASE_SERVICE_ROLE_KEY;
const supaAuth = { 'apikey': SUPA_KEY, 'Authorization': 'Bearer ' + SUPA_KEY, 'Prefer': 'return=minimal' };
const calAuth = { 'Authorization': 'Bearer ' + CAL_TOKEN };
const bookingRefsAuth = { 'Authorization': 'Bearer ' + CAL_TOKEN, 'cal-api-version': '2024-08-13' };

function sleep(ms) {
  return new Promise(function(resolve) { setTimeout(resolve, ms); });
}

function shortJson(value) {
  return JSON.stringify(value || {}).slice(0, 300);
}

function buildCalendarDescription(bookingUid, startLabel) {
  const lines = [
    'Resumo do Lead - Nexos',
    '',
    'Nome: ' + (orig._name || 'Lead'),
    'WhatsApp: ' + (phone ? '+' + phone : 'nao informado'),
    'Email tecnico: ' + (finalEmail || 'nao informado'),
    'Horario agendado: ' + startLabel,
    'UID Cal.com: ' + bookingUid,
    '',
    'Resumo para a reuniao:',
    leadSummary || 'Resumo nao informado pelo agente.',
    '',
    'Origem: automacao SDR WhatsApp / Nexos'
  ];
  return lines.join(String.fromCharCode(10));
}

function getReferenceArray(response) {
  if (!response) return [];
  if (Array.isArray(response.data)) return response.data;
  if (response.data && Array.isArray(response.data.references)) return response.data.references;
  if (Array.isArray(response.references)) return response.references;
  return [];
}

async function findGoogleCalendarEventUid(bookingUid) {
  for (let attempt = 1; attempt <= 4; attempt++) {
    const refs = await this.helpers.httpRequest({
      method: 'GET',
      url: BASE + '/bookings/' + encodeURIComponent(bookingUid) + '/references',
      headers: bookingRefsAuth,
      qs: { type: 'google_calendar' },
      ignoreHttpStatusErrors: true
    });

    const refList = getReferenceArray(refs);
    const googleRef = refList.find(function(ref) {
      return ref && (!ref.type || ref.type === 'google_calendar') && (ref.eventUid || ref.uid || ref.externalId || ref.id);
    });

    if (googleRef) {
      return {
        eventUid: String(googleRef.eventUid || googleRef.uid || googleRef.externalId || googleRef.id),
        raw: googleRef
      };
    }

    if (attempt < 4) await sleep(700 * attempt);
  }

  return { eventUid: '', raw: null };
}

async function updateGoogleCalendarDescription(bookingUid, description) {
  if (!leadSummary) return 'CALENDAR_DESC_SKIP: resumo vazio';

  const googleEvent = await findGoogleCalendarEventUid.call(this, bookingUid);
  if (!googleEvent.eventUid) {
    return 'CALENDAR_DESC_WARN: nao encontrei referencia google_calendar no booking';
  }

  const updateResp = await this.helpers.httpRequest({
    method: 'PATCH',
    url: BASE + '/calendars/google/events/' + encodeURIComponent(googleEvent.eventUid),
    headers: Object.assign({ 'Content-Type': 'application/json' }, calAuth),
    body: { description },
    ignoreHttpStatusErrors: true
  });

  if (updateResp && updateResp.status === 'success') return 'CALENDAR_DESC_OK';
  return 'CALENDAR_DESC_WARN: ' + shortJson(updateResp);
}

if (calResp && calResp.status === 'success' && calResp.data && calResp.data.uid) {
  const bookingUid = calResp.data.uid;
  const startStr = orig._start || '';
  const dt = new Date(startStr);
  const dateStr = dt.toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', year: 'numeric' });
  const timeStr = dt.toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' });
  const startLabel = dateStr + ' as ' + timeStr;
  const calendarDescription = buildCalendarDescription(bookingUid, startLabel);
  const calendarNote = await updateGoogleCalendarDescription.call(this, bookingUid, calendarDescription);

  if (phone.length >= 12) {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: SUPA_URL + '/leads_outbound',
      headers: supaAuth,
      qs: { phone: 'eq.' + phone, niche: 'eq.advocacia' },
      body: { meeting_scheduled_at: new Date().toISOString(), meeting_link: 'https://cal.com/nexos-group-10x-b21jks/30min', status: 'meeting_scheduled' },
      ignoreHttpStatusErrors: true
    });
  }
  return [{ json: { output: 'BOOKING_OK: Reuniao agendada para ' + startLabel + '. UID=' + bookingUid + ' | ' + calendarNote } }];
}
return [{ json: { output: 'Erro Cal.com: ' + JSON.stringify(calResp).slice(0, 400) + ' | start=' + orig._start + ' email=' + finalEmail } }];
